import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.kOe0DhAP.js";const p=JSON.parse('{"title":"风控与异常处理","description":"重点处理线下支付事实与内部订单状态之间的不一致。","frontmatter":{"title":"风控与异常处理","description":"重点处理线下支付事实与内部订单状态之间的不一致。"},"headers":[],"relativePath":"otc/risk.md","filePath":"otc/risk.md"}'),i={name:"otc/risk.md"};function s(d,a,c,l,n,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<div class="doc-eyebrow">OTC 手册 / TGEX KNOWLEDGE BASE</div><h1 id="风控与异常处理" tabindex="-1">风控与异常处理 <a class="header-anchor" href="#风控与异常处理" aria-label="Permalink to &quot;风控与异常处理&quot;">​</a></h1><div class="doc-lead">重点处理线下支付事实与内部订单状态之间的不一致。</div><h2 id="典型问题" tabindex="-1">典型问题 <a class="header-anchor" href="#典型问题" aria-label="Permalink to &quot;典型问题&quot;">​</a></h2><p>买方标记付款但实际未付、支付方与下单身份不一致、卖方收款后未放币、同一订单重复通知，属于不同风险场景，不能用一个“失败退款”动作统一处理。</p><h2 id="核对顺序" tabindex="-1">核对顺序 <a class="header-anchor" href="#核对顺序" aria-label="Permalink to &quot;核对顺序&quot;">​</a></h2><p>先锁定订单编号与双方身份，再核对平台状态、资金占用、支付证据和最近操作。涉及申诉时，普通自动任务应遵守争议处理规则。</p><h2 id="一致性目标" tabindex="-1">一致性目标 <a class="header-anchor" href="#一致性目标" aria-label="Permalink to &quot;一致性目标&quot;">​</a></h2><p>广告数量、订单剩余量、托管资产和最终到账需要互相解释。人工处理也应通过可追踪的业务操作完成，避免直接改数据库后缺少资金依据。</p>',9)])])}const m=e(i,[["render",s]]);export{p as __pageData,m as default};
